# Test: 0s transform if they have clear horizontal line-of-sight to marker column (col 7)
# Line of sight means only 9s between them

def has_clear_line_of_sight(cell, grid, target_col=7):
    r, c = cell
    # Check if horizontal path to target_col is clear (only 9s and 0s)
    if c < target_col:
        # Check cells between c and target_col
        for cc in range(c, target_col):
            if grid[r][cc] not in [0, 9]:
                return False
    else:
        # Check cells between c and target_col
        for cc in range(c+1, target_col+1):
            if grid[r][cc] not in [0, 9]:
                return False
    return True

# Or vertical line of sight
def has_clear_vertical_view(cell, grid, target_row=7):
    r, c = cell
    # Check if vertical path to target_row is clear
    for rr in range(min(r, target_row)+1, max(r, target_row)):
        if grid[rr][c] not in [0, 9]:
            return False
    return True

